  1→import { useState } from "react";
  2→import { Badge } from "@/components/ui/badge";
  3→import { Button } from "@/components/ui/button";
  4→import { Cpu, ChevronDown, ChevronUp, AlertTriangle } from "lucide-react";
  5→import type { Result } from "@/pages/Index";
  6→
  7→interface SkillsDetailPanelProps {
  8→  result: Result;
  9→}
 10→
 11→type SkillLevel = "Expert" | "Adv" | "Good" | "Mid" | "Low" | "Gap";
 12→
 13→const getSkillLevel = (score: number): { label: SkillLevel; cls: string } => {
 14→  if (score >= 90) return { label: "Expert", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
 15→  if (score >= 70) return { label: "Adv", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
 16→  if (score >= 55) return { label: "Good", cls: "bg-teal-500/10 text-teal-600 border-teal-200 dark:text-teal-400 dark:border-teal-800" };
 17→  if (score >= 40) return { label: "Mid", cls: "bg-yellow-500/10 text-yellow-700 border-yellow-200 dark:text-yellow-400 dark:border-yellow-800" };
 18→  if (score >= 20) return { label: "Low", cls: "bg-orange-500/10 text-orange-600 border-orange-200 dark:text-orange-400 dark:border-orange-800" };
 19→  return { label: "Gap", cls: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800" };
 20→};
 21→
 22→const getOverallLabel = (score: number): { text: string; cls: string } => {
 23→  if (score >= 80) return { text: "Expert", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
 24→  if (score >= 65) return { text: "Advanced", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
 25→  if (score >= 50) return { text: "Good", cls: "bg-teal-500/10 text-teal-600 border-teal-200 dark:text-teal-400 dark:border-teal-800" };
 26→  if (score >= 30) return { text: "Mid", cls: "bg-yellow-500/10 text-yellow-700 border-yellow-200 dark:text-yellow-400 dark:border-yellow-800" };
 27→  return { text: "Low", cls: "bg-orange-500/10 text-orange-600 border-orange-200 dark:text-orange-400 dark:border-orange-800" };
 28→};
 29→
 30→const SkillsDetailPanel = ({ result: r }: SkillsDetailPanelProps) => {
 31→  const [showAll, setShowAll] = useState(false);
 32→  const scores = r.category_scores_json;
 33→  const gaps = Array.isArray(r.gaps_json) ? r.gaps_json.map(String) : [];
 34→  const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.map(String) : [];
 35→
 36→  // Parse and sort skills
 37→  const entries = scores && typeof scores === "object" && !Array.isArray(scores)
 38→    ? Object.entries(scores as Record<string, any>).map(([skill, data]) => {
 39→        const score = data && typeof data === "object" ? (data.score ?? 0) : (typeof data === "number" ? data : 0);
 40→        const clamped = Math.max(0, Math.min(score, 100));
 41→        const level = getSkillLevel(clamped);
 42→        return { skill, score: clamped, level };
 43→      }).sort((a, b) => b.score - a.score)
 44→    : [];
 45→
 46→  const skillCount = entries.length;
 47→  const strongCount = entries.filter((e) => e.score >= 55).length;
 48→  const gapCount = entries.filter((e) => e.score < 20).length;
 49→
 50→  // Overall match score
 51→  const overallScore = skillCount > 0
 52→    ? Math.round(entries.reduce((sum, e) => sum + e.score, 0) / skillCount)
 53→    : 0;
 54→  const overallLabel = getOverallLabel(overallScore);
 55→
 56→  // Top skills (score >= 55) for chips — show max 4
 57→  const topSkills = entries.filter((e) => e.score >= 55).slice(0, 4);
 58→
 59→  // Gap skills for gap rows
 60→  const gapSkills = entries.filter((e) => e.score < 20);
 61→
 62→  // Also include gaps from gaps_json that aren't in category scores
 63→  const scoreSkillNames = new Set(entries.map((e) => e.skill.toLowerCase().replace(/_/g, " ")));
 64→  const extraGaps = [...missing, ...gaps]
 65→    .filter((g) => !scoreSkillNames.has(g.toLowerCase()))
 66→    .slice(0, 3);
 67→
 68→  // Collapsed: show top chips + gaps only; Expanded: show all skills
 69→  const visibleEntries = showAll ? entries : [];
 70→
 71→  return (
