 37→/** Infer education level from degree name for icon + rank */
 38→type EduLevel = "doctorate" | "masters" | "bachelors" | "diploma" | "higher_secondary" | "secondary" | "other";
 39→
 40→const inferLevel = (degree: string): EduLevel => {
 41→  const d = degree.toLowerCase();
 42→  if (d.includes("phd") || d.includes("doctorate") || d.includes("d.phil")) return "doctorate";
 43→  if (d.includes("master") || d.includes("mba") || d.includes("m.sc") || d.includes("m.tech") || d.includes("m.e.") || d.includes("m.a.") || d.includes("msc") || d.includes("m.com")) return "masters";
