 67→  higher_secondary: { label: "Tier 2", cls: "bg-muted text-muted-foreground border-border" },
 68→  secondary: { label: "Secondary", cls: "bg-muted text-muted-foreground border-border" },
 69→  other: { label: "Other", cls: "bg-muted text-muted-foreground border-border" },
