 72→/** Is this a low-relevance qualification? (secondary school etc.) */
 73→const isLowRelevance = (level: EduLevel): boolean =>
 74→  level === "secondary" || level === "higher_secondary";
 75→
 76→/** Match score label */
 77→const getScoreLabel = (score: number): { text: string; cls: string } => {
 78→  if (score >= 75) return { text: "Strong", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
 79→  if (score >= 50) return { text: "Good", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
 80→  if (score >= 25) return { text: "Partial", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
 81→  return { text: "Weak", cls: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800" };
