 31→const getMatchLabel = (score: number): { text: string; v: ColorVariant } => {
 32→  if (score >= 70) return { text: "Strong match", v: "green" };
 33→  if (score >= 50) return { text: "Good match",   v: "blue" };
 34→  if (score >= 30) return { text: "Partial match", v: "amber" };
 35→  return { text: "Weak match", v: "red" };
 36→};
 37→
 38→const getConfidenceLabel = (c: number): { text: string; v: ColorVariant } => {
 39→  if (c >= 70) return { text: "High confidence",   v: "green" };
 40→  if (c >= 40) return { text: "Medium confidence", v: "amber" };
 41→  return { text: "Low confidence", v: "red" };
 42→};
 43→
 44→const getRecommendation = (score: number, hardFit: boolean | undefined, isHeuristic: boolean): { text: string; v: ColorVariant } => {
 45→  if (isHeuristic) return { text: "Needs full AI scoring for reliable recommendation", v: "amber" };
 46→  if (score >= 70 && hardFit !== false)
 47→    return { text: "Shortlist — strong core fit, gaps are learnable", v: "green" };
 48→  if (score >= 50 && hardFit !== false)
 49→    return { text: "Consider — decent match, review before interview", v: "blue" };
 50→  if (score >= 40)
 51→    return { text: "Review — has strengths but missing critical items", v: "amber" };
 52→  return { text: "Pass — significant gaps for this role", v: "red" };
 53→};
