178→                  <span className="text-muted-foreground flex-1 leading-snug">{item}</span>
179→                  <Badge variant="outline" className={`text-[9px] shrink-0 ${VARIANT_CLS.amber}`}>Not Met</Badge>
180→                </div>
181→              ))}
182→              {matchedPreferred.length === 0 && missingPreferred.length === 0 && (
183→                <p className="text-xs text-muted-foreground italic">No preferred data</p>
184→              )}
185→            </div>
186→          </div>
187→
188→          {/* AI INSIGHT */}
189→          <div className="space-y-2">
190→            <span className="text-[10px] uppercase tracking-wider text-score-overall font-semibold flex items-center gap-1">
191→              <Lightbulb className="h-3 w-3" /> AI Insight
192→            </span>
193→
194→            {r.explanation_json?.why_ranked_here && (
195→              <p className="text-[11px] text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
196→            )}
197→
198→            {/* Recommendation */}
199→            <div className={`p-2 rounded text-[11px] font-medium border ${PILL_CLS[rec.v]}`}>
200→              <span className="text-[9px] uppercase tracking-wider font-semibold block mb-0.5 opacity-70">Recommendation</span>
201→              {rec.text}
202→            </div>
203→
204→            {/* Interview Focus */}
205→            {interviewQs.length > 0 && (
206→              <div className="p-2 rounded bg-purple-500/5 border border-purple-500/20 dark:border-purple-500/30 text-[11px]">
207→                <span className="text-[9px] uppercase tracking-wider font-semibold text-purple-600 dark:text-purple-400 block mb-0.5">
208→                  Interview Focus
209→                </span>
210→                <span className="text-muted-foreground leading-relaxed">{interviewQs[0]}</span>
211→              </div>
212→            )}
213→
214→            {/* Key trade-offs */}
215→            {r.explanation_json?.key_tradeoffs && (
216→              <p className="text-[10px] text-muted-foreground leading-relaxed italic">
217→                {r.explanation_json.key_tradeoffs}
218→              </p>
219→            )}
220→          </div>
221→
222→        </div>
223→      </div>
224→
225→      {/* ── AI Suggestion Bar (read-only insight) ──────────── */}
226→      {missing.length + missingPreferred.length > 0 && (
227→        <div className="px-4 py-2.5 border-t border-border bg-muted/20 flex items-center gap-3">
228→          <Lightbulb className="h-3.5 w-3.5 text-amber-500 shrink-0" />
229→          <p className="text-xs text-muted-foreground flex-1">
230→            <span className="font-medium text-foreground">AI suggestion</span>{" "}
231→            Softening{" "}
232→            <span className="font-medium">{missing[0] || missingPreferred[0]}</span>{" "}
233→            requirements may surface more qualified candidates for this role
234→          </p>
235→        </div>
236→      )}
237→    </div>
238→  );
239→};
240→
241→export default JDAlignedPanel;
