 3→import { ChevronDown, ChevronUp } from "lucide-react";
 4→import type { Result } from "@/pages/Index";
 5→
 6→interface InterviewQuestionsPanelProps {
 7→  result: Result;
 8→}
 9→
10→const InterviewQuestionsPanel = ({ result: r }: InterviewQuestionsPanelProps) => {
