13→
14→  if (!questions || !Array.isArray(questions) || questions.length === 0) return null;
15→
16→  // First question is shown as "Interview Focus" in JD Aligned panel — show remaining here
17→  const remaining = questions.slice(1);
18→  if (remaining.length === 0) return null;
19→
20→  return (
21→    <div>
22→      <Button
23→        variant="ghost"
24→        size="sm"
25→        className="h-7 px-2 text-xs text-muted-foreground hover:text-foreground gap-1"
26→        onClick={() => setIsOpen(!isOpen)}
27→      >
28→        More Interview Questions ({remaining.length})
29→        {isOpen ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
30→      </Button>
31→      {isOpen && (
32→        <ol start={2} className="text-sm list-decimal list-inside space-y-1 text-muted-foreground mt-2 pl-2">
33→          {remaining.map((q: any, i: number) => <li key={i}>{typeof q === "string" ? q : String(q)}</li>)}
34→        </ol>
35→      )}
36→    </div>
37→  );
38→};
